             doc.RegistrationFrozen ||
             doc.PendingStage is not null ||
             doc.PhaseAuthorization is not null ||
             (doc.BaselineObservations?.Count ?? 0) != 0))
            throw new InvalidDataException(
                "migration_protocol_undeclared_or_unoccupied_journal");

