    private void AdmitPersistentMutation(
        string entryName,
        ProtocolFacts facts,
        bool allowAbsent = false)
    {
        if (facts.Kind is PersistentProtocolKind.Unknown or
                          PersistentProtocolKind.UnverifiableModern)
