743ae24320040a3053ebf984558fbaa78a66cb","id":"IMPLEMENTATION-CALLBACK-NOFLOW-1","severity":"important","obligation":"implementation","root_cause":"Lock-free callback rejection depends on AsyncLocal CallbackOwner flowing to a worker. Arbitrary supported callbacks can use SuppressFlow or UnsafeQueueUserWorkItem; the worker sees no owner and waits for the monitor held by its waiting callback."},{"key":"10077d95df4bfcdfc4b1503f5c085f9770a2d88c45057052f93f21f850e5bdb2","id":"R1-IMPORTANT-8","severity":"important","obligation":"implementation","root_cause":"异常边界和故障注入位置曾没有覆盖完整链。"},{"key":"100c8a548a7ae9eb20e5ad5bb5014b14528fd70ce6013db7f3cb46f661179e4a","id":"FACILITY-NATIVE-MIXED-RESULTS-1","severity":"important","obligation":"implementation","root_cause":"现有 implementation_proofs 对每个已认证 execution.results 无条件调用 parse_trx。合法 writer JSON 因此导致 ParseError。V11 的声明测试路径分派方向正确，但尚未实施和认证，本次方案审查不能关闭该实施义务。"},{"key":"1839b05fef6252eb9e5354ed60f77a78f4670f54bb27f89651e7be64f8a07758","id":"R5-MUST-2","severity":"must","obligation":"implementation","root_cause":"已核验输入、预测结果、实际撤销字节和恢复授权没有贯穿绑定；候选修复只解决预测入口的一个TOCTOU窗口。"},{"key":"191a1b54041c6b51bab28890fec9c724111e14ba90c5c4ebbaf14936ba7683b0","id":"IMPLEMENTATION-PRODUCTION-GATE-1","severity":"must","obligation":"implementation","root_cause":"AuthorizeProductionExecution 只检查持久 manifest 的 Committed/marker/证据字段，TryRunProduction 随后执行传入 Action。实际 prepared 隔离事务可以走到 Committed，这条 API 没有落实方案保留的真实生产 Action 拒绝边界。"},{"key":"1e14c1069375a146ad1c742e3a0bbaa4eee500f27af08c38064de6648acfa544","id":"G4-residual","severity":"important","obligation":"implementation","root_cause":"cursor generation design undecided; send-side frozen recheck missing; AMD-1-3 parent reference not persisted"},{"key":"218c0e85e883f4f2887bbdc3430847446858eac85c3e170133c205f2b29e5e14","id":"R2-IMPORTANT-5","severity":"important","obligation":"implementation","root_cause":"不存在目标曾被错误要求提供实际写入证据。"},{"key":"29b92201f595505f2f486647893530e996dab8c91b7d205998ded24ebaa20346","id":"R1-IMPORTANT-7","severity":"important","obligation":"implementation","root_cause":"状态相等曾被误用为已执行证据，转换入口未限定合同。"},{"key":"2e8eda421da1c26ab33b3c1224f4f84b6e278823917cfc951f0adef80bebd8b1","id":"PLAN-SNAPSHOT-1","severity":"important","obligation":"plan","root_cause":"V12 的旧工具 67 收据/22 PFP、候选 recipes、完整历史 rollout 和 e127 certifier archive 已实际进入冻结集合，但当前产品认证闭包没有随最新 V15 manifest 投影。manifest 当前 execution_evidence 与 mutation 三段去重共 46 份 receipt，冻结合同仅包含其中 v5 historical baseline；其余 45 份当前 receipt 均不可读。original-e127-full-audit-resume-v11.json 包含 c49 final 的派生 record/conditions/rows，却没有该 final 的原 receipt 及依赖闭包。这仍未满足 69648 原 PLAN-SNAPSHOT-1 要求的比较 final 原件可读条件。"},{"key":"344c65d6ea19e8161761cdf8906caffa3b97865e742bddb15eba04f0d690db91","id":"PLAN-EVIDENCE-PROJECTION-SNAPSHOT-1","severity":"important","obligation":"plan","root_cause":"本请求明确要求审查当前风险映射是否造成误闭合，但plan冻结合同只有历史矩阵副本和manifest中的历史投影，没有实际current矩阵。native_review.prepare在plan阶段设置authenticated=[]，因此manifest引用的当前矩阵、current执行和PFP不会自动进入合同。冻结manifest.risk_matrix仍为native-recovery-20261001/risk-matrix-current-v13.json，opening.risk_matrix则为原risk-matrix.json；PLAN-v6所述原路径承载当前投影尚不是本快照中可核验的事实。"},{"key":"34a9033b309579ed2aeb6821d6c5c3bcd9de2adf946488d531208cb7ce2ae3a4","id":"IMPLEMENTATION-RESTORE-OWNERSHIP-1","severity":"must","obligation":"implementation","root_cause":"恢复授权没有覆盖全baseline，且恢复原地覆写；最终旧态一致会掩盖他方数据被破坏。"},{"key":"382074e4e248b39d47426478b4a153f8bb2c12798e8f5e2caf49a6d804e361ad","id":"R5-IMPORTANT-4","severity":"important","obligation":"implementation","root_cause":"回调生命周期与外层持久化操作生命周期不一致。"},{"key":"391707af8d335b974e6b6c1f7b53e9306db2533f694180beeddd7df5bc103b43","id":"IMPLEMENTATION-FORWARD-VERSION-1","severity":"must","obligation":"implementation","root_cause":"首次引用更新没有事务输入版本绑定，正向读回只有语义成立加当前哈希，没有独立预期输出版本。"},{"key":"3d9c50253025051f2b735634abc18b8952b5e7cc835c2eef6e6eb6bf50e38720","id":"R1-IMPORTANT-6","severity":"important","obligation":"implementation","root_cause":"声明变更可以在证据形成后变化，破坏精确写集。"},{"key":"4003e782b9085d3c4cecdcee9899fe01857bde30f7d7c9ea5e52cb9db3bdeac3","id":"IMPLEMENTATION-ABORT-TERMINAL-REOPEN-1","severity":"important","obligation":"implementation","root_cause":"A no-baseline safe abort publishes RolledBack with ControlledBaseline absent. The next Prepared instance's RecoverOnStart unconditionally calls RefreshControlledWitness for RolledBack, which reports controlled_root_baseline_missing and changes that legitimate terminal back to Blocked."},{"key":"4566983eeb6cf2af71b3a31923c6623bf9105b70e987a21d2b3f008d6fbd69dd","id":"FACILITY-NATIVE-MIXED-RESULTS-1","severity":"important","obligation":"implementation","root_cause":"implementation_proofs无条件把所有认证results当TRX；真实writer JSON被parse_trx拒绝，阻止原生实现收据发布。V13修法位于原层且保留全部认证门。"},{"key":"46096d4d8a47320fbf7e2f795c67417ec9a41fbc44b6869b57b788ff4235a389","id":"R5-IMPORTANT-7","severity":"important","obligation":"implementation","root_cause":"当前认证关系和计数已修复，但关键风险到反例的因果映射仍有缺口，不能将正常prepared路径证明泛化到成功早返回或能力降级。"},{"key":"4ab1dd0f5ec555faea419bbd30d50b153803c768be2837729922ec596f661b49","id":"FACILITY-PREPARE-CHECKPOINT-DERIVED-PRIOR-1","severity":"important","obligation":"implementation","root_cause":"prepare globs every checkpoints/*.json including adapter-generated N-prior dictionaries; prior_register assumes findings list of original objects and calls get on string dictionary keys."},{"key":"4e1b389817b8e8cd14c921943a2a23692dda571689f30246856fc2fe44fb4c43","id":"R5-IMPORTANT-6","severity":"important","obligation":"implementation","root_cause":"恢复窗口声明与实际测试执行路径不一致。"},{"key":"4fb81c415485a6d082cb6f86c9784892dee5feb01570a0b278f4264f696ee313","id":"FACILITY-NATIVE-MIXED-RESULTS-1","severity":"important","obligation":"implementation","root_cause":"implementation_proofs把ee.validate已经认证的每个execution.results都交给workflow.parse_trx；合法mixed结果中的controlled-writer-evidence.json因此触发XML ParseError，阻止原生receipt出版。"},{"key":"576ed2a63dfa779a7848f0181e306a14318158ccc5fe037a0c980241c0ed4358","id":"R5-IMPORTANT-4","severity":"important","obligation":"implementation","root_cause":"DisposeRequested 能延后资源释放，但新公开操作尚未统一拒绝该终结请求。TryAcquireExclusive 仍可重新取得锁，BeginOperation 也不检查请求。"},{"key":"5838cab28d6ea0adfb2f6a7cfe0bdcda69a682f5372d659b0d6c9a7d05b0771f","id":"CONTROL-RELEASE-ATOMICITY-1","severity":"must","obligation":"plan","root_cause":"方案只要求Host终局回写及最终重读检查同一事实集合，没有定义释放资格如何与并发发送/受理写者线性化。当前Host从RunStore读一次终态后逐操作MarkOperationTerminal，最后仅重读受理存储；单加一次最终RunStore重读仍可能在已经错误释放后才发现事实变化。Paused停止只检查旧CurrentSubmission.InFlight；Cancelled重试直接进入终局回写；异常收敛跳过所有终态。方案也没有精确定义前置Intent/Submitted/Unknown、主体Rejected但SendAttempted、收尾pending/dispatching/submitted等组合的清偿表。"},{"key":"5b6d4adb2ee7017edbdaca0d2c14a7dbca55bb98b62fba58bdbf9f2bfb9a32b9","id":"G4a-residual","severity":"important","obligation":"implementation","root_cause":"real entry/machine evidence for startup handoff missing"},{"key":"5c87c26e801236c8f5dff1c6f22f8af9c391ef211907076a36c6638599c2196a","id":"R5-IMPORTANT-7","severity":"important","obligation":"implementation","root_cause":"已认证正常 prepared 路径的映射仍不能证明能力降级、幂等早返回和 nojournal 成功资格；历史标签、关键反例与当前证明必须继续逐项对齐。"},{"key":"61e922a03c8eadf3ee75d355f329081be9794449bd29cad9f16ea76f6746ead7","id":"CONTROL-RUN-LIFECYCLE-1","severity":"must","obligation":"plan","root_cause":"首审要求耐久Stop、不可变运行基线、无驱动恢复及自动触发所属生命周期。v2 §1/3/4/5已定义StopAuthority与单调StopRequested、原受理落盘、恢复/重放不重新基准化、FireSteps继承挂载来源、现有撤销入口和实际面板对账。新增同机单调意图时间与最近ManualStop标记处理未Ready期间延迟捕获基线，仍保持版本单一权威。只关闭方案义务，不关闭尚未实现的行为。"},{"key":"653c8ca3d50e9ba5e4ea9e83553ed3a9892ad0b87f8c87905256d0c89d139134","id":"IMPLEMENTATION-NOJOURNAL-PUBLICATION-FRESH-1","severity":"important","obligation":"implementation","root_cause":"PublishPreparedMain 在调用发布前 stageHook 后，只在有 journal 分支重新 RefreshControlledWitness。无 journal 分支直接序列化 requested 与之前取得的 ControlledLatest。因此完整基线已建立的 SnapshotReady、无数据操作的 RolledBack，以及对应无 journal 终态重开，可以把回调前见证作为回调后成功发布的资格。此处尚未形成与有 journal 分支相同的成功资格协议。"}]
using System.Security.Cryptography;
using System.Text.Json;
using MultiplayerHoeingAssistant.Models;

namespace MultiplayerHoeingAssistant.Services;

public sealed partial class RunStore
{
    internal bool TryPrepareSubmission(string runId, Func<WorkflowRunRecord, bool> apply,
        out WorkflowRunRecord? latest, string? originalSendIdentity = null)
    {
        var permit = new PreparedSendPermit(1, Guid.NewGuid().ToString("N"), false, originalSendIdentity);
        return UpdateMergingCore(runId, current =>
        {
            if (current.CurrentSubmission is not { } submission) return false;
            var renewal = CanRenewPreparedSubmission(current, submission, originalSendIdentity);
            if (submission.SendPermit is not null && !renewal) return false;
            if (submission.SendPermit is null && (submission.PreviousSendRounds is not null
                || originalSendIdentity is not null && RoundSequence(originalSendIdentity) == 0)) return false;
            var previous = renewal ? new DischargedNodeSendRound(submission.SendPermit!, submission.LocalNoSendProof!, submission.OriginalRequestEvidence!) : null;
            if (!apply(current)) return false;
            if (previous is not null)
            {
                (submission.PreviousSendRounds ??= []).Add(previous);
                submission.LocalNoSendProof = null;
            }
            submission.SendPermit = permit;
            return true;
        }, out latest, permit);
    }

    internal static bool CanRenewPreparedSubmission(WorkflowRunRecord run, WorkflowSubmission submission, string? nextIdentity)
        => !run.StopRequested && submission.SendPermit is { Version: 1, Consumed: true, OriginalSendIdentity: not null } permit
            && Guid.TryParseExact(permit.Nonce, "N", out _) && submission.OriginalRequestEvidence is not null
            && LocalNoSendEvidence.IsDischarged(run, submission)
            && submission.LocalNoSendProof is { Kind: LocalNoSendEvidence.TransportNotSent }
            && PreviousRoundsComplete(run, submission, permit)
            && NextSendRound(permit.OriginalSendIdentity, nextIdentity);

    private static int RoundSequence(string? identity)
    {
        if (identity is null || !identity.StartsWith("sub:", StringComparison.Ordinal)) return 0;
        var separator = identity.LastIndexOf(':');
        return separator > 4 && int.TryParse(identity[(separator + 1)..], out var seq) && seq > 0
            && identity == identity[..(separator + 1)] + seq.ToString(System.Globalization.CultureInfo.InvariantCulture) ? seq : 0;
    }

    private static bool PreviousRoundsComplete(WorkflowRunRecord run, WorkflowSubmission sub, PreparedSendPermit permit)
    {
        var sequence = RoundSequence(permit.OriginalSendIdentity);
        var rounds = sub.PreviousSendRounds ?? [];
        if (sequence < 1 || rounds.Any(r => r is null || r.Permit is null || r.Proof is null || r.RequestEvidence is null)
            || rounds.Count != sequence - 1
            || rounds.Select(r => r.Permit.Nonce).Append(permit.Nonce).Distinct(StringComparer.Ordinal).Count() != sequence) return false;
        var prefix = permit.OriginalSendIdentity![..(permit.OriginalSendIdentity.LastIndexOf(':') + 1)];
        return !rounds.Where((r, i) => r.Permit.OriginalSendIdentity != prefix + (i + 1).ToString(System.Globalization.CultureInfo.InvariantCulture)
            || !LocalNoSendEvidence.PriorRoundMatches(run, sub, r)).Any();
    }

    internal static bool NextSendRound(string? prior, string? next)
    {
        if (prior is null || next is null || !prior.StartsWith("sub:", StringComparison.Ordinal)) return false;
        var separator = prior.LastIndexOf(':');
        return separator > 4 && int.TryParse(prior[(separator + 1)..], out var seq) && seq > 0 && seq < int.MaxValue
            && prior == prior[..(separator + 1)] + seq.ToString(System.Globalization.CultureInfo.InvariantCulture)
            && next == prior[..(separator + 1)] + (seq + 1).ToString(System.Globalization.CultureInfo.InvariantCulture);
    }

    internal bool TryConsumePreparedSubmission(BgiWorkflowExecutionBoundary.PreparedSubmit prepared,
        out WorkflowRunRecord? latest)
    {
        latest = null;
        if (prepared.Run is not { } run || prepared.Reconcile is not { } identity
            || prepared.FrozenPermit is not { Version: 1, Consumed: false } permit
            || prepared.Payload is null || prepared.FrozenFingerprint is null) return false;
        var raw = JsonSerializer.Serialize(prepared.Payload);
        if (Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(raw)))[..24].ToLowerInvariant() != prepared.FrozenFingerprint
            || identity.RequestEvidence is not { } evidence
            || BgiOriginalRequestFingerprint.Compute(prepared.Operation, raw) != evidence.Fingerprint) return false;
        var consumed = permit with { Consumed = true };
        lock (_gate)
        {
            var applied = UpdateMergingCore(run.RunId, current =>
            {
                var s = current.CurrentSubmission;
                if (current.TerminalRelease is not null || s is null || s.SendPermit != permit
                    || current.StopAuthority != prepared.FrozenStopAuthority || current.WireRunId != identity.WireRunId
                    || s.Key != identity.Key || s.Epoch != identity.Epoch || s.NodeId != identity.NodeId
                    || s.Occurrence != identity.Occurrence || s.LoopIteration != identity.LoopIteration || s.Attempt != identity.Attempt
                    || s.Fingerprint != prepared.FrozenFingerprint || s.OriginalRequestEvidence != evidence
                    || s.Intent != SubmitIntentState.Submitted || !s.SendAttempted
                    || !string.IsNullOrEmpty(s.JobId) || !string.IsNullOrEmpty(s.AcceptedSendIdentity)
                    || s.LocalNoSendProof is not null || s.ObservedTerminal is not null || s.ExecutionExitConfirmed
                    || current.Cursor is not { } cursor || cursor.NodeId != identity.NodeId
                    || cursor.Occurrence != identity.Occurrence || cursor.LoopIteration != identity.LoopIteration
                    || cursor.Attempt != identity.Attempt) return false;
                s.SendPermit = consumed;
                return true;
            }, out var published, consumed);
            if (!applied || published is null) return false;
            // A failed/unknown readback never restores an unconsumed permit.
            var readback = Load(run.RunId);
            if (readback?.RecordRevision != published.RecordRevision || readback.CurrentSubmission?.SendPermit != consumed) return false;
            latest = readback;
            return true;
        }
    }
}

