                    lock (Sync)
                    {
                        if (_disposed) return;
                        StopReason = "lease_expired";
                        Observe(TaskRunResult.Cancelled);
                        MarkStopRequestedLocked("lease_expired");
                    }
                    try { _stop.Cancel(); } catch (AggregateException) { }
                }
            }, null, TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(5));
