                {
                    probeState = null; // 单轮探测失败不终止等待（BGI 冷启动中管道未就绪是常态），下一轮再试；取消不吞
                }

                if (_externalClient?.State == BgiExternalLinkState.Ready)
                {
                    AddLog("[任务中心] BGI 外部接口通道已就绪，继续执行");
