    private async Task<ProbeOutcome> TryProbeExternalChannelAsync(DateTime? deadlineUtc, bool forceProbe, CancellationToken ct)
    {
        // 会诊四轮 阻断修复：预算耗尽判定仅限有预算调用——InfiniteTimeSpan(-1ms) 会被 <= Zero 误判耗尽（轮询路径永禁）
