    public static Task<(string Outcome, BgiJobInfo? Job, string? Reason)> PollUntilTerminalAsync(
        BgiExternalClient client, string jobId, TimeSpan budget, TimeSpan interval, CancellationToken ct)
        => PollUntilTerminalAsync(
