            if (audits.Count != 1) return null;
            var facts = handoff.ReconciledNotAcceptedEvidence.Where(e => e.EvidenceId == audits[0].ResolutionEvidenceRef!.EvidenceId
                && e.SubmissionIdentity == identity && e.SendSeq == seq && e.ObservedAtUtc != default
                && !string.IsNullOrEmpty(e.EvidenceSource) && !string.IsNullOrEmpty(e.RawEvidenceWord)
                && ReconciledNotAcceptedFactKinds.All.Contains(e.FactKind)).ToList();
            if (facts.Count != 1 || op.ConflictEvidence.Any(e => e.SubmissionIdentity == identity
