            if (snapshot.State == JobState.Succeeded && expectedKind == JobKind.Prerequisite && !cancelled)
            {
                RecordTerminal(item.TaskHandle, "completed");
                PublishSafe(ExternalInterfaceEventNames.TaskCompleted, new
