        if (snapshot is { State: JobState.Queued or JobState.Running or JobState.Cancelling })
            JobRegistry.Instance.TryMarkUnknown(item.TaskHandle, snapshot.ErrorCode ?? "result_unknown", snapshot.ErrorMessage);
