    private async Task<bool> WaitSlotFreeAsync(PendingTask item, CancellationToken pumpToken)
    {
        var timeout = item.Submission.Preempt ? TimeSpan.FromSeconds(3) : _slotWaitTimeout;
        var deadline = DateTime.UtcNow + timeout;
